cssRules:
.step-tracker {
  display: flex;
  align-items: center;
  gap: 8px;
}
.step {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  color: #71717a;
}
.circle {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  font-weight: 600;
  background: #27272a;
  color: #a1a1aa;
}
.step.current {
  color: #ffffff;
}
.step.current .circle {
  background: #3b82f6;
  color: #ffffff;
}
.step.completed .circle {
  background: #10b981;
  color: #ffffff;
}
.line {
  flex: 1;
  height: 2px;
  background: #27272a;
}
.line.completed {
  background: #10b981;
}
